// Non-secret settings for ff-dataforseo. n8n credentials: FF Supabase (service
// role) and FF DataForSEO (Basic Auth: API login + password). Google Ads values
// come from the dashboard Settings page ("Get Google Ads secrets").
// Weekly (Monday 05:00) and from the dashboard ("Refresh keyword data").
// Webhook body (optional): { client_id } to research one client only.
const SETTINGS = {
  SUPABASE_URL: 'https://SET-ME.supabase.co',
  SUPABASE_ANON_KEY: 'SET-ME',
  GOOGLE_ADS_API_VERSION: 'v25',
  ALLOWED_ROLES: ['rob_admin', 'ff_staff'],
  RELATED_SEEDS_PER_CLIENT: 5, // DataForSEO related-keywords calls per client per run
  RELATED_PER_SEED: 20,
};

const src = $input.first().json || {};
const fromWebhook = Boolean(src.headers);
const body = fromWebhook && src.body && typeof src.body === 'object' ? src.body : {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

return [{
  json: {
    ...SETTINGS,
    body,
    trigger: fromWebhook ? 'manual' : 'schedule',
    only_client_id: typeof body.client_id === 'string' && uuid.test(body.client_id) ? body.client_id : null,
  },
}];

// Auth check block 1/4 - read the bearer token. Never log it.
const headers = $('Webhook').first().json.headers || {};
const raw = headers.authorization || headers.Authorization || '';
const match = /^Bearer\s+(\S+)$/i.exec(String(raw).trim());
return [{ json: { token: match ? match[1] : '' } }];

// Auth check block 4/4 - decide. Output: { ok, status, error?, user? }
const cfg = $('Config').first().json;
const token = $('Auth: read token').first().json.token;
const userRes = $('Auth: verify token').first().json;
const profileRes = $('Auth: load profile').first().json;

const deny = (status, error) => [{ json: { ok: false, status, error } }];

if (!token) return deny(401, 'Missing login token.');
if (userRes.statusCode !== 200 || !userRes.body || !userRes.body.id) {
  return deny(401, 'Login token is not valid or has expired.');
}
if (profileRes.statusCode !== 200) return deny(500, 'Could not load the login profile.');

const rows = Array.isArray(profileRes.body) ? profileRes.body : [];
const profile = rows[0];
if (!profile || profile.user_id !== userRes.body.id) return deny(403, 'This login has no access.');
if (profile.disabled) return deny(403, 'This login has been turned off.');
if (!cfg.ALLOWED_ROLES.includes(profile.role)) {
  return deny(403, 'Your role does not allow this action.');
}

return [{
  json: {
    ok: true,
    status: 200,
    user: {
      user_id: profile.user_id,
      email: profile.email,
      role: profile.role,
      client_id: profile.client_id,
    },
  },
}];

// One item per client with keywords to research (ff_keyword_research_targets:
// our positive keywords, negatives and non-name search terms, most spend first).
// { none: true } when there is nothing, so the loop is skipped cleanly.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.client_id && Array.isArray(r.keywords) && r.keywords.length);
if (!rows.length) return [{ json: { none: true } }];
return rows.map((r) => ({
  json: {
    client_id: r.client_id,
    customer_id: r.customer_id,
    login_customer_id: r.login_customer_id || null,
    location_code: Number(r.location_code) || 2840,
    language_code: r.language_code || 'en',
    keywords: r.keywords.slice(0, 1000),
    seeds: (r.seeds || []).filter(Boolean),
    geo_targets: (r.geo_targets || []).filter(Boolean).slice(0, 10),
  },
}));

// Request bodies for the current client:
//   DataForSEO  keywords_data/google_ads/search_volume/live (up to 1000 keywords)
//   Google Ads  KeywordPlanIdeaService.GenerateKeywordHistoricalMetrics (read only)
const t = $('Loop over clients').first().json;
const LANGUAGES = { en: 'languageConstants/1000', fr: 'languageConstants/1002', es: 'languageConstants/1003' };

const googleBody = {
  keywords: t.keywords,
  keywordPlanNetwork: 'GOOGLE_SEARCH',
  language: LANGUAGES[t.language_code] || LANGUAGES.en,
  historicalMetricsOptions: { includeAverageCpc: true },
};
if (t.geo_targets.length) googleBody.geoTargetConstants = t.geo_targets;

return [{
  json: {
    ...t,
    dataforseo_body: [{ keywords: t.keywords, location_code: t.location_code, language_code: t.language_code }],
    google_body: googleBody,
  },
}];

// One item per seed keyword for DataForSEO related keywords. Always at least one
// item ({ skip: true }) so the loop keeps going when a client has no seeds.
const cfg = $('Config').first().json;
const t = $('Build requests').first().json;
const seeds = t.seeds.slice(0, cfg.RELATED_SEEDS_PER_CLIENT);
if (!seeds.length) return [{ json: { skip: true, seed: null, body: [] } }];
return seeds.map((seed) => ({
  json: {
    skip: false,
    seed,
    body: [{ keyword: seed, location_code: t.location_code, language_code: t.language_code, limit: cfg.RELATED_PER_SEED }],
  },
}));

// DataForSEO + Google Keyword Planner responses -> keyword_volume rows
// (source 'dataforseo' / 'google_kp'), cached per month. Related keywords are
// stored on the seed's DataForSEO row. Rows in one request share the same keys.
const t = $('Build requests').first().json;
const dfs = $('DataForSEO search volume').first().json || {};
const kp = $('Google keyword metrics').first().json || {};
const relatedInputs = $input.all();

const now = new Date();
const month = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}-01`;
const syncedAt = now.toISOString();
const norm = (s) => String(s || '').toLowerCase().trim().replace(/\s+/g, ' ');
const intOrNull = (v) => (v === null || v === undefined || v === '' ? null : Math.round(Number(v)));
const microsFromMoney = (v) => (v === null || v === undefined || v === '' ? null : Math.round(Number(v) * 1e6));
const ok = (r) => r && r.statusCode >= 200 && r.statusCode < 300;

const rows = new Map();
function put(row) {
  const key = [row.source, row.keyword_norm, row.geo_target, row.language, row.fetched_month].join('|');
  const prev = rows.get(key);
  rows.set(key, prev ? { ...prev, ...row, related_keywords: row.related_keywords.length ? row.related_keywords : prev.related_keywords } : row);
}
const base = (source, keyword, geo) => ({
  source, keyword_norm: norm(keyword), geo_target: geo, language: t.language_code, fetched_month: month,
  avg_monthly_searches: null, competition: null, competition_index: null, low_top_bid_micros: null,
  high_top_bid_micros: null, avg_cpc_micros: null, monthly_searches: [], related_keywords: [], synced_at: syncedAt,
});

const errors = [];

// DataForSEO search volume
const dfsTask = ok(dfs) && dfs.body && dfs.body.tasks && dfs.body.tasks[0];
if (dfsTask && dfsTask.status_code === 20000) {
  for (const r of dfsTask.result || []) {
    if (!r || !r.keyword) continue;
    put({
      ...base('dataforseo', r.keyword, String(t.location_code)),
      avg_monthly_searches: intOrNull(r.search_volume),
      competition: r.competition || null,
      competition_index: intOrNull(r.competition_index),
      low_top_bid_micros: microsFromMoney(r.low_top_of_page_bid),
      high_top_bid_micros: microsFromMoney(r.high_top_of_page_bid),
      avg_cpc_micros: microsFromMoney(r.cpc),
      monthly_searches: (r.monthly_searches || []).map((x) => ({ year: x.year, month: x.month, searches: x.search_volume })),
    });
  }
} else {
  errors.push(`DataForSEO search volume: ${(dfsTask && dfsTask.status_message) || (dfs.body && dfs.body.status_message) || `status ${dfs.statusCode}`}`);
}

// Google Keyword Planner historical metrics
if (ok(kp)) {
  for (const r of (kp.body && kp.body.results) || []) {
    const km = r.keywordMetrics || {};
    if (!r.text) continue;
    put({
      ...base('google_kp', r.text, ''),
      avg_monthly_searches: intOrNull(km.avgMonthlySearches),
      competition: km.competition || null,
      competition_index: intOrNull(km.competitionIndex),
      low_top_bid_micros: intOrNull(km.lowTopOfPageBidMicros),
      high_top_bid_micros: intOrNull(km.highTopOfPageBidMicros),
      avg_cpc_micros: intOrNull(km.averageCpcMicros),
      monthly_searches: (km.monthlySearchVolumes || []).map((x) => ({ year: x.year, month: x.month, searches: intOrNull(x.monthlySearches) })),
    });
  }
} else {
  errors.push(`Google Keyword Planner: status ${kp.statusCode}`);
}

// Related keywords (one response per seed)
relatedInputs.forEach((item, i) => {
  let seedItem;
  try {
    seedItem = $('Related seeds').itemMatching(i).json;
  } catch (e) {
    seedItem = ($('Related seeds').all()[i] || {}).json || {};
  }
  if (!seedItem || seedItem.skip) return;
  const r = item.json || {};
  const task = ok(r) && r.body && r.body.tasks && r.body.tasks[0];
  const result = task && task.result && task.result[0];
  if (!result) {
    errors.push(`Related keywords for one seed: ${(task && task.status_message) || `status ${r.statusCode}`}`);
    return;
  }
  const related = (result.items || []).slice(0, 50).map((x) => {
    const kd = x.keyword_data || {};
    const info = kd.keyword_info || {};
    return { keyword: kd.keyword, volume: intOrNull(info.search_volume), cpc: info.cpc ?? null, competition: info.competition_level || null };
  }).filter((x) => x.keyword);
  const key = ['dataforseo', norm(seedItem.seed), String(t.location_code), t.language_code, month].join('|');
  const existing = rows.get(key) || base('dataforseo', seedItem.seed, String(t.location_code));
  rows.set(key, { ...existing, related_keywords: related });
});

const all = [...rows.values()];
const out = [];
for (let i = 0; i < all.length; i += 500) out.push({ json: { rows: all.slice(i, i + 500), errors } });
if (!out.length) out.push({ json: { rows: [], errors } });
return out;
